export const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));

export function analysisPayload(data, ids) {
  const selected = new Set(ids);
  const choices = data.choices.filter(c => selected.has(c.id)).map(c => ({
    id: c.id, question: c.question, chosen: c.chosen, reason_quote: c.reason_quote,
    context: {project_key: c.context.project_key, conditions: c.context.conditions || []},
    source_refs: c.source_refs,
  }));
  if (!choices.length || choices.length > 60 || choices.length !== selected.size)
    throw new Error('분석할 기록을 1개에서 60개 사이로 골라주세요.');
  const refs = new Set(choices.flatMap(c => c.source_refs));
  const criteria = data.criteria.flatMap(c => c.versions.filter(v => refs.has(v.ref)).map(v => ({
    ref: v.ref, statement: v.statement, confirmation: v.confirmation,
    current: v.version === c.current_version, revoked: c.revoked,
    applies_when: v.applies_when || [], exceptions: v.exceptions || [],
  })));
  const payload = {choices, criteria};
  if (JSON.stringify(payload).length > 55000 || criteria.length > 100)
    throw new Error('분석할 내용이 너무 길어요. 기록을 더 적게 골라주세요.');
  return payload;
}

export function aiSection(analysis, busy, count) {
  return '<section class="ai-section"><div class="section-heading"><div><span class="small-label">나를 한 번 더 들여다봐요</span>'
    + '<h2>' + (analysis ? escape(analysis.headline) : '선택 사이에는 어떤 이야기가 있을까요?') + '</h2></div></div>'
    + (analysis ? '<p class="ai-summary">' + escape(analysis.summary) + '</p><div class="ai-insights">'
      + analysis.insights.map((item, i) => '<article class="ai-insight"><span class="pill">AI가 읽어본 이야기</span><h3>'
        + escape(item.title) + '</h3><p>' + escape(item.interpretation) + '</p><details><summary>다르게 볼 수도 있어요</summary><p>'
        + escape(item.alternative) + '</p></details><button class="text-button" data-action="ai-evidence" data-index="'
        + i + '">근거가 된 ' + item.evidence_ids.length + '개의 선택 보기 ↗</button></article>').join('')
      + '</div><div class="reflection-question"><b>나에게 남기는 질문</b><p>' + escape(analysis.next_question) + '</p></div>'
      + '<p class="quiet">' + analysis.limitations.map(escape).join(' ') + '</p>'
      + '<button class="text-button" data-action="ai-note">해석에 내 생각 더하기</button>'
      : '<p>고른 기록을 Claude가 읽고, 반복된 선택과 그때의 사정을 짚어드려요.<br>해석마다 어떤 기록을 읽었는지 함께 보여드려요.</p>')
    + '<button class="button ink" data-action="ai-select" ' + (busy || !count ? 'disabled' : '') + '>'
    + (busy ? 'Claude가 기록을 읽고 있어요…' : analysis ? '다른 기록으로 다시 돌아보기' : 'AI와 나의 선택 돌아보기')
    + '</button><p class="quiet">' + (analysis ? escape(analysis.analyzed_at) + ' · ' + analysis.selected_ids.length + '개의 기록을 분석했어요. ' : '')
    + '분석할 기록을 직접 고릅니다. AI의 해석은 저장된 기준과 구분해요.</p></section>';
}

export function selectionHtml(data, mode, enabled) {
  if (!enabled) return '<p>이 뷰어에서는 Claude 분석을 아직 켜지 않았어요.</p>'
    + '<p>Claude CLI에 로그인한 컴퓨터에서 아래 명령으로 실행하면 사용할 수 있어요.</p>'
    + '<pre>python3 avatar/scripts/avatar_web.py --ai claude</pre>'
    + '<p class="quiet">기본 요약, 리포트와 규칙 내려받기는 계속 사용할 수 있어요.</p>';
  return '<p>' + (mode === 'demo' ? '지금은 설명용 예시 기록입니다.' : '직접 가져온 기록입니다.')
    + ' Claude가 읽을 기록을 골라주세요. 최대 60개까지 함께 볼 수 있어요.</p>'
    + '<button class="text-button" data-action="ai-pick">앞의 30개까지 한 번에 고르기</button>'
    + '<div class="selection-list">' + data.choices.map(c => '<label class="check-label"><input type="checkbox" name="ai-choice" value="'
      + escape(c.id) + '"><span><b>' + escape(c.question) + '</b><small>'
      + escape(c.context.project_key) + ' · ' + escape(c.chosen) + '</small></span></label>').join('') + '</div>'
    + '<details open><summary>Claude에 보낼 내용 전체 보기</summary><pre id="ai-payload" class="rules-preview"></pre></details>'
    + '<p>선택한 질문·선택·이유·상황과 참조한 기준을 Claude로 보냅니다. 현재 로그인한 Claude 계정의 사용량이 소모됩니다.</p>'
    + '<label class="check-label"><input type="checkbox" id="ai-consent">위 내용을 확인했고, 고른 기록을 보내 분석하겠습니다.</label>'
    + '<button class="button ink" id="ai-start" data-action="ai-start" disabled>고른 기록으로 분석하기</button>'
    + '<p class="quiet">원본은 바뀌지 않아요. 결과는 이 탭에만 남으므로 간직하려면 리포트를 내려받으세요.</p>';
}

export function aiMarkdown(analysis) {
  if (!analysis) return '';
  const line = text => String(text).replace(/[\r\n]+/g, ' ');
  const quote = text => String(text).split(/\r\n|\r|\n/).map(part => '> ' + part).join('\n');
  return '\n\n## AI와 돌아본 선택\n\n### ' + line(analysis.headline) + '\n\n' + quote(analysis.summary)
    + '\n\n분석 시각: ' + analysis.analyzed_at + '\n분석한 기록: ' + analysis.selected_ids.join(', ')
    + '\n\n' + analysis.insights.map(item => '### ' + line(item.title) + '\n\n' + quote(item.interpretation)
      + '\n\n다르게 볼 가능성:\n' + quote(item.alternative) + '\n근거: ' + item.evidence_ids.map(line).join(', ')).join('\n\n')
    + '\n\n나에게 남기는 질문:\n' + quote(analysis.next_question) + '\n\n한계:\n' + quote(analysis.limitations.join('\n'))
    + '\n\nAI의 해석이며 사용자가 확인한 개인 기준이 아닙니다.\n';
}

